function switchMainTab(tab){
  document.querySelectorAll('.main-tab').forEach(el=> el.classList.toggle('active', el.dataset.tab===tab));
  document.querySelectorAll('.tab-panel').forEach(el=> el.classList.remove('active'));
  document.getElementById('tab-'+tab).classList.add('active');
  if(tab==='documents') renderDocumentsTray();
}

/* ============================================================
   DOCUMENTS TRAY (combine + print)
   ============================================================ */
let documents = [];
const lastGenerated = {}; // {itinerary: html, flight: html, hotel: html, car: html}

function addCurrentToDocuments(type){
  const html = lastGenerated[type];
  if(!html){ alert('Generate the document first.'); return; }
  const labels = {itinerary:'Itinerary', flight:'Flight Voucher', hotel:'Hotel Voucher', car:'Car Transfer Voucher'};
  documents.push({ id: Date.now()+Math.random(), type, label: labels[type], html, selected:true });
  renderDocumentsTray();
  switchMainTab('documents');
}
function removeDocument(id){ documents = documents.filter(d=>d.id!==id); renderDocumentsTray(); }
function clearDocuments(){ documents = []; renderDocumentsTray(); }
function toggleDocSelected(id, checked){ const d=documents.find(x=>x.id===id); if(d) d.selected = checked; }

function renderDocumentsTray(){
  document.getElementById('doc-count').textContent = documents.length;
  const list = document.getElementById('documents-list');
  if(!documents.length){
    list.innerHTML = '<div class="empty-state">No documents added yet. Generate an itinerary or voucher, then click "+ Add to My Documents".</div>';
    return;
  }
  list.innerHTML = documents.map(d=>`
    <div class="doc-chip">
      <input type="checkbox" ${d.selected?'checked':''} onchange="toggleDocSelected(${d.id}, this.checked)">
      <span class="dtype">${d.type}</span>
      <span class="dlabel">${esc(d.label)}</span>
      <button class="btn btn-text" onclick="removeDocument(${d.id})">Remove</button>
    </div>`).join('');
}

function openPrintWindow(bodyHtml){
  const cssHref = new URL('css/document-studio.css', window.location.href).href;
  const styles = `<link rel="stylesheet" href="${cssHref}">`;
  const w = window.open('', '_blank');
  if(!w){
    alert('Your browser blocked this as a pop-up.\n\nPlease allow pop-ups for this page (usually a small icon in the address bar), then click the print button again.\n\nIf you opened this tool inside a preview window rather than a normal browser tab, try downloading the file and opening it directly in Chrome/Edge/Firefox instead.');
    return;
  }
  w.document.open();
  w.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Print</title>' + styles + '</head><body>' + bodyHtml + '</body></html>');
  w.document.close();
  const doPrint = function(){ try{ w.focus(); w.print(); }catch(e){} };
  if(w.document.readyState === 'complete'){ setTimeout(doPrint, 300); }
  else { w.onload = function(){ setTimeout(doPrint, 300); }; }
}

function printOne(type){
  const html = lastGenerated[type];
  if(!html){ alert('Generate the document first.'); return; }
  openPrintWindow(`<div class="doc">${html}</div>`);
}

function printSelectedDocuments(){
  const chosen = documents.filter(d=>d.selected);
  if(!chosen.length){ alert('Select at least one document to print.'); return; }
  openPrintWindow(chosen.map(d=>`<div class="doc">${d.html}</div>`).join(''));
}

