async function itRunExtraction(){
  const text = document.getElementById('it-raw-text').value.trim();
  if(!text){ alert('Please upload a file or paste itinerary text first.'); return; }
  itRawText = text;
  const btn = document.getElementById('it-extract-btn'); const progress = document.getElementById('it-progress-1');
  btn.disabled = true; progress.className='progress';
  try{
    progress.textContent = 'Extracting trip overview, hotels and cost...';
    const p1 = `Read this raw travel itinerary text supplied by a DMC and extract ONLY the following as strict JSON — no markdown fences, no commentary. If a field isn't present, use "" or [].
Schema: {"overview": {"tripRef": string, "destination": string, "startDate": string, "duration": string, "travelers": string}, "notes": [string], "hotels": [{"dateRange": string, "nights": number, "city": string, "hotelName": string, "stars": number, "mealPlan": string, "room": string}], "cost": {"perPerson": string, "pax": string, "total": string, "note": string}}
Raw text: """${text}"""`;
    const r1 = await callClaude(p1);
    state.overview = r1.overview || state.overview;
    state.hotels = r1.hotels || [];
    state.cost = r1.cost || state.cost;
    state.overview.notes = r1.notes || [];

    progress.textContent = 'Finding the days in the itinerary...';
    const p2 = `Read this raw DMC itinerary text and return ONLY strict JSON listing every day: {"days": [{"dayNumber": number, "title": string, "date": string}]}
Raw text: """${text}"""`;
    const r2 = await callClaude(p2);
    const dayList = r2.days || [];
    state.days = dayList.map(d=>({...d, description:'', tags:[]}));

    const batchSize = 3;
    for(let i=0;i<dayList.length;i+=batchSize){
      const batch = dayList.slice(i,i+batchSize);
      progress.textContent = `Extracting day details ${i+1}–${Math.min(i+batchSize,dayList.length)} of ${dayList.length}...`;
      const nums = batch.map(d=>d.dayNumber).join(', ');
      const p3 = `Read this raw DMC itinerary text. For ONLY day numbers [${nums}], write a concise 2-3 sentence description and 2-4 short tag labels. Return ONLY strict JSON: {"days": [{"dayNumber": number, "description": string, "tags": [string]}]}
Raw text: """${text}"""`;
      const r3 = await callClaude(p3);
      (r3.days||[]).forEach(d=>{ const t = state.days.find(x=>x.dayNumber===d.dayNumber); if(t){ t.description=d.description||''; t.tags=d.tags||[]; } });
    }
    progress.textContent = 'Done — review the details below.';
    populateReviewForm(); itGoStep(2);
  }catch(err){
    progress.className='progress err'; progress.textContent = 'Extraction error: ' + err.message + '. You can fill details manually in step 2.';
    populateReviewForm(); itGoStep(2);
  }finally{ btn.disabled = false; }
}

