let flState = { pnr:'',bookingRef:'',issued:'',status:'Confirmed', passengers:[], segments:[], fare:{base:'',taxes:'',fees:'',total:''}, notes:[] };
let flRawText = "";

function flGoStep(n){
  document.getElementById('fl-step-1').style.display = n===1?'block':'none';
  document.getElementById('fl-step-2').style.display = n===2?'block':'none';
  document.getElementById('fl-step-3').style.display = n===3?'block':'none';
  [1,2,3].forEach(i=>{ const p=document.getElementById('fl-pill-'+i); p.classList.toggle('active', i===n); p.classList.toggle('done', i<n); });
  if(n===2 && flState.passengers.length===0 && flState.segments.length===0){ flAddPassenger(); flAddSegment(); populateFlightForm(); }
}
