let htState = { confNo:'',status:'Confirmed',checkIn:'',checkOut:'',hotelName:'',address:'',stars:4,phone:'',nights:'', guests:[], rooms:[], amount:'',payStatus:'',cancelPolicy:'', notes:[] };
