function htGoStep(n){
  document.getElementById('ht-step-1').style.display = n===1?'block':'none';
  document.getElementById('ht-step-2').style.display = n===2?'block':'none';
  document.getElementById('ht-step-3').style.display = n===3?'block':'none';
  [1,2,3].forEach(i=>{ const p=document.getElementById('ht-pill-'+i); p.classList.toggle('active', i===n); p.classList.toggle('done', i<n); });
  if(n===2 && htState.guests.length===0 && htState.rooms.length===0){ htAddGuest(); htAddRoom(); populateHotelForm(); }
}
wireDropZone('ht-drop-zone','ht-file-input', handleHtFile);
async function handleHtFile(file){
  document.getElementById('ht-file-chip-holder').innerHTML = `<div class="filename-chip">📄 ${file.name}</div>`;
  const progress = document.getElementById('ht-progress-1');
  try{ const text = await readFileToText(file, progress); htRawText = text; document.getElementById('ht-raw-text').value = text; }
  catch(err){ progress.className='progress err'; progress.textContent = err.message; }
}
document.getElementById('ht-raw-text').addEventListener('input', e=> htRawText = e.target.value);

async function htRunExtraction(){
  const text = document.getElementById('ht-raw-text').value.trim();
  if(!text){ alert('Please upload a file or paste the hotel voucher text first.'); return; }
  htRawText = text;
  const btn = document.getElementById('ht-extract-btn'); const progress = document.getElementById('ht-progress-1');
  btn.disabled = true; progress.className='progress'; progress.textContent = 'Extracting hotel booking details...';
  try{
    const p = `Read this hotel booking confirmation / voucher text and extract ONLY the following as strict JSON — no markdown fences, no commentary. If a field isn't present use "" or [].
Schema: {"confNo": string, "status": string, "checkIn": string, "checkOut": string, "nights": string,
"hotel": {"name": string, "address": string, "stars": number, "phone": string},
"guests": [{"title": string, "firstName": string, "lastName": string, "roomNo": string}],
"rooms": [{"roomType": string, "mealPlan": string, "occupancy": string}],
"amount": {"total": string, "payStatus": string},
"cancelPolicy": string,
"notes": [string]  // key remarks, terms, policies — max 6, concise
}
Raw text: """${text}"""`;
    const r = await callClaude(p);
    htState.confNo = r.confNo||''; htState.status = r.status||'Confirmed'; htState.checkIn = r.checkIn||''; htState.checkOut = r.checkOut||''; htState.nights = r.nights||'';
    const h = r.hotel||{}; htState.hotelName = h.name||''; htState.address = h.address||''; htState.stars = h.stars||4; htState.phone = h.phone||'';
    htState.guests = r.guests||[]; htState.rooms = r.rooms||[];
    const a = r.amount||{}; htState.amount = a.total||''; htState.payStatus = a.payStatus||'';
    htState.cancelPolicy = r.cancelPolicy||''; htState.notes = r.notes||[];
    if(!htState.guests.length) htState.guests = [{title:'',firstName:'',lastName:'',roomNo:'1'}];
    if(!htState.rooms.length) htState.rooms = [{roomType:'',mealPlan:'',occupancy:''}];
    progress.textContent = 'Done — review the details below.';
    populateHotelForm(); htGoStep(2);
  }catch(err){
    progress.className='progress err'; progress.textContent = 'Extraction error: ' + err.message + '. Fill details manually below.';
    htGoStep(2);
  }finally{ btn.disabled = false; }
}

