  const statusHtml = `<div><span class="status-badge${htState.status.toLowerCase().includes('confirm')?'':' pending'}">${esc(htState.status)}</span> <span class="refbit">Confirmation No: <strong>${esc(htState.confNo)}</strong></span></div>`;
