wireDropZone('cv-drop-zone','cv-file-input', handleCvFile);
async function handleCvFile(file){
  document.getElementById('cv-file-chip-holder').innerHTML = `<div class="filename-chip">📄 ${file.name}</div>`;
  const progress = document.getElementById('cv-progress-1');
  try{ const text = await readFileToText(file, progress); cvRawText = text; document.getElementById('cv-raw-text').value = text; }
  catch(err){ progress.className='progress err'; progress.textContent = err.message; }
}
document.getElementById('cv-raw-text').addEventListener('input', e=> cvRawText = e.target.value);

async function cvRunExtraction(){
  const text = document.getElementById('cv-raw-text').value.trim();
  if(!text){ alert('Please upload a file or paste some confirmation text first, or click "Skip — fill form manually".'); return; }
  cvRawText = text;
  const btn = document.getElementById('cv-extract-btn'); const progress = document.getElementById('cv-progress-1');
  btn.disabled = true; progress.className='progress'; progress.textContent = 'Extracting transfer details...';
  try{
    const p = `Read this car/transfer booking confirmation text (could be an informal vendor email or message) and extract ONLY the following as strict JSON — no markdown fences, no commentary. If a field isn't present use "".
Schema: {"confNo": string, "status": string, "date": string, "time": string, "pickup": string, "drop": string, "passenger": string, "passContact": string, "vehicle": string, "driver": string, "driverContact": string, "vendor": string, "ref": string, "fare": string, "notes": [string]}
Raw text: """${text}"""`;
    const r = await callClaude(p);
    Object.assign(cvState, r);
    cvState.notes = r.notes && r.notes.length ? r.notes : cvState.notes;
    progress.textContent = 'Done — review the details below.';
    populateCarForm(); cvGoStep(2);
  }catch(err){
    progress.className='progress err'; progress.textContent = 'Extraction error: ' + err.message + '. Fill details manually below.';
    cvGoStep(2);
  }finally{ btn.disabled = false; }
}

function populateCarForm(){
  document.getElementById('cv-confno').value = cvState.confNo||'';
  document.getElementById('cv-status').value = cvState.status||'Confirmed';
  document.getElementById('cv-date').value = cvState.date||'';
  document.getElementById('cv-time').value = cvState.time||'';
  document.getElementById('cv-pickup').value = cvState.pickup||'';
  document.getElementById('cv-drop').value = cvState.drop||'';
  document.getElementById('cv-passenger').value = cvState.passenger||'';
  document.getElementById('cv-passcontact').value = cvState.passContact||'';
  document.getElementById('cv-vehicle').value = cvState.vehicle||'';
  document.getElementById('cv-driver').value = cvState.driver||'';
  document.getElementById('cv-drivercontact').value = cvState.driverContact||'';
  document.getElementById('cv-vendor').value = cvState.vendor||'';
  document.getElementById('cv-ref').value = cvState.ref||'';
  document.getElementById('cv-fare').value = cvState.fare||'';
  if(cvState.notes && cvState.notes.length) document.getElementById('cv-notes').value = cvState.notes.join('\n');
}

function cvGoToOutput(){
  cvState.confNo = document.getElementById('cv-confno').value;
  cvState.status = document.getElementById('cv-status').value;
  cvState.date = document.getElementById('cv-date').value;
  cvState.time = document.getElementById('cv-time').value;
  cvState.pickup = document.getElementById('cv-pickup').value;
  cvState.drop = document.getElementById('cv-drop').value;
  cvState.passenger = document.getElementById('cv-passenger').value;
  cvState.passContact = document.getElementById('cv-passcontact').value;
  cvState.vehicle = document.getElementById('cv-vehicle').value;
  cvState.driver = document.getElementById('cv-driver').value;
  cvState.driverContact = document.getElementById('cv-drivercontact').value;
  cvState.vendor = document.getElementById('cv-vendor').value;
  cvState.ref = document.getElementById('cv-ref').value;
  cvState.fare = document.getElementById('cv-fare').value;
  cvState.notes = document.getElementById('cv-notes').value.split('\n').map(s=>s.trim()).filter(Boolean);

  const cfg = getCompanyCfg();
  const statusHtml = `<div><span class="status-badge${cvState.status.toLowerCase().includes('confirm')?'':' pending'}">${esc(cvState.status)}</span> <span class="refbit">Confirmation No: <strong>${esc(cvState.confNo)}</strong></span></div>`;

  const html = `
    ${docHeader(cfg, 'Car Transfer Voucher', statusHtml)}
    <div class="doc-body">
      <div class="section-label">TRANSFER DETAILS</div>
      <div class="overview-card">
        <div class="meta-grid">
          <div><span>Date</span><strong>${esc(cvState.date)}</strong></div>
          <div><span>Pickup Time</span><strong>${esc(cvState.time)}</strong></div>
          <div><span>Vehicle</span><strong>${esc(cvState.vehicle)}</strong></div>
          <div><span>Reference</span><strong>${esc(cvState.ref)}</strong></div>
        </div>
        <div class="route" style="margin-top:14px;border-top:1px dashed var(--line);padding-top:16px">
          <div class="route-stop"><strong>${esc(cvState.pickup)||'Pickup'}</strong><span>Pickup</span></div>
          <span class="route-arrow">→</span>
          <div class="route-stop"><strong>${esc(cvState.drop)||'Drop'}</strong><span>Drop-off</span></div>
        </div>
      </div>
      <div class="section-label">PASSENGER &amp; DRIVER</div>
      <div class="two-col">
        <div class="info-block">
          <h4>Passenger</h4>
          <p>${esc(cvState.passenger)}</p>
          ${cvState.passContact?`<p>${esc(cvState.passContact)}</p>`:''}
        </div>
        <div class="info-block">
          <h4>Driver / Vendor</h4>
          <p>${esc(cvState.driver)}${cvState.driverContact?(' · '+esc(cvState.driverContact)):''}</p>
          ${cvState.vendor?`<p>${esc(cvState.vendor)}</p>`:''}
        </div>
      </div>
      ${cvState.fare?`
      <div class="section-label">FARE</div>
      <div class="cost-card"><div><div class="label">Total Fare</div><div class="big">${esc(cvState.fare)}</div></div></div>`:''}
      ${notesBlock(cvState.notes)}
    </div>
    <div class="doc-footer">Issued by <strong>${esc(cfg.name)}</strong> · ${esc(cfg.address)} · ${esc(cfg.phones)}</div>`;

  document.getElementById('cv-doc-root').innerHTML = html;
  lastGenerated.car = html;
  cvGoStep(3);
}

renderDocumentsTray();
